<template><div class="print-page" v-loading="loading"><div class="toolbar"><el-button @click="$router.back()">返回</el-button><el-button type="primary" @click="printPage">打印追责单</el-button></div><section v-if="data.id" class="sheet"><h1>万悦城运营检查问题追责单</h1><div class="number">追责单号：{{data.orderNo}}</div><table><tbody><tr><th>日清日期</th><td>{{data.period_date}}</td><th>铺位编码</th><td>{{data.stallCode}}</td></tr><tr><th>商户名称</th><td>{{data.merchantName||'-'}}</td><th>检查人员</th><td>{{data.inspectorName}}</td></tr><tr><th>检查时间</th><td colspan="3">{{formatDateTime(data.inspectedAt)}}</td></tr><tr><th>异常问题</th><td colspan="3" class="large">{{data.issueDescription}}</td></tr><tr><th>责任人</th><td>{{data.responsibleName||''}}</td><th>联系电话</th><td>{{data.responsiblePhone||''}}</td></tr><tr><th>整改要求</th><td colspan="3" class="large">{{data.correctiveAction||''}}</td></tr><tr><th>整改期限</th><td>{{formatDateTime(data.deadlineAt)}}</td><th>处理状态</th><td>{{statusText[data.status]||data.status}}</td></tr><tr><th>处理结果</th><td colspan="3" class="result">{{data.handlingResult||''}}</td></tr><tr><th>处理人</th><td>{{data.handledBy||''}}</td><th>完成时间</th><td>{{formatDateTime(data.resolvedAt)}}</td></tr></tbody></table><div class="sign"><span>责任人签字：</span><span>复核人签字：</span><span>日期：</span></div></section></div></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{useRoute}from'vue-router';import{operationAccountabilityApi}from'@/api/operation';import{formatDateTime}from'@/utils/format';const route=useRoute(),data=reactive<any>({}),loading=ref(false),statusText:Record<string,string>={PENDING:'待处理',PROCESSING:'处理中',RESOLVED:'已整改',CLOSED:'已关闭'};function printPage(){window.print()}onMounted(async()=>{loading.value=true;try{Object.assign(data,await operationAccountabilityApi.detail(Number(route.params.id)))}finally{loading.value=false}});</script>
<style scoped>.print-page{min-height:100vh;background:#eee;padding:24px}.toolbar{width:210mm;margin:0 auto 12px;display:flex;justify-content:flex-end;gap:10px}.sheet{box-sizing:border-box;width:210mm;min-height:297mm;margin:auto;padding:18mm;background:#fff;color:#111}h1{text-align:center;font-size:26px;margin:0 0 8px}.number{text-align:right;margin-bottom:14px}table{width:100%;border-collapse:collapse;font-size:15px}th,td{border:1px solid #333;padding:10px;vertical-align:top}th{width:15%;background:#f4f4f4}td{width:35%}.large{height:72px}.result{height:110px}.sign{display:flex;justify-content:space-between;margin-top:55px}@media print{.print-page{padding:0;background:#fff}.toolbar{display:none}.sheet{margin:0;padding:15mm;min-height:auto}}@media(max-width:850px){.print-page{padding:8px;overflow:auto}.toolbar,.sheet{width:210mm}}</style>
